VARIANTS = {
 "1j": dict(version="Compact_2_1 Rev1", game="g1",
            src_md5="af355adec937a9db1d447980bf85aa2e",
            out_name="Super Robot Taisen Compact 2 - Dai-1-bu - Chijou Gekidou Hen (Japan)(Skip).ws"),
 "2j": dict(version="Compact_2_2 Rev4", game="g2",
            src_md5="bb1cf0d7237d7ae2c8aac562fc62906d",
            out_name="Super Robot Taisen Compact 2 - Dai-2-bu - Uchuu Gekishin Hen (Japan) (Rev 4)(Skip).ws"),
 "3j": dict(version="Compact_2_3 Rev2", game="g3",
            src_md5="44f63dcb11c916df900a128a6f2e3839",
            out_name="Super Robot Taisen Compact 2 - Dai-3-bu - Ginga Kessen Hen (Japan) (Rev 2)(Skip).ws"),
 "1h": dict(version="地上激震篇 v2.1汉化版", game="g1",
            src_md5="6973fc92049623f4a653bae1b8f26a85",
            out_name="第2次机器人大战-地上激震篇_汉化版_v2.1_跳过动画.ws"),
 "2h": dict(version="宇宙激震篇 v1.5汉化版", game="g2",
            src_md5="a4099985dcf1c518e8ce091950b28c43",
            out_name="第2次机器人大战-宇宙激震篇_汉化版_v1.5_跳过动画.ws"),
 "3h": dict(version="银河决战篇 v1.7汉化版", game="g3",
            src_md5="06df34700b425d4d79e80e6c74d550a8",
            out_name="第2次机器人大战-银河决战篇_汉化版_v1.7_跳过动画.ws"),
}


def all_regions(key):
    return MENU[key] + combat_regions(VARIANTS[key]["game"])


def md5(b):
    return hashlib.md5(b).hexdigest()


def apply_patch(data, key):
    out = bytearray(data)
    regs = all_regions(key)
    placed = []
    for reg in regs:
        b = bytes.fromhex(reg[1]) if isinstance(reg[1], str) else bytes(reg[1])
        for off2, end2 in placed:
            assert reg[0] + len(b) <= off2 or end2 <= reg[0],                 "region overlap at %06X (%d B)" % (reg[0], len(b))
        placed.append((reg[0], reg[0] + len(b)))
    for reg in all_regions(key):
        off, hexs = reg[0], reg[1]
        b = bytes.fromhex(hexs) if isinstance(hexs, str) else bytes(hexs)
        out[off:off + len(b)] = b
    return bytes(out)


def detect(data):
    h = md5(data)
    for k, v in VARIANTS.items():
        if h == v["src_md5"]:
            return k, "src"
    for k, v in VARIANTS.items():
        if h == md5(apply_patch(data, k)):
            return k, "dst"
    return None, h


def main(args):
    force = "--force" in args
    args = [a for a in args if a != "--force"]
    if len(args) < 1:
        print("用法: python build_rom_v2.py <source.ws|.wsc> [output] [--force]")
        return 2
    src_path = args[0]
    data = open(src_path, "rb").read()
    if len(data) != ROM_SIZE:
        print("ROM 大小不是 4MB:", len(data))
        return 2
    key, state = detect(data)
    if key is None:
        print("未识别的 ROM: MD5=%s" % state)
        for k, v in VARIANTS.items():
            print("  %-3s %-28s src MD5 %s" % (k, v["version"], v["src_md5"]))
        return 2
    v = VARIANTS[key]
    if state == "dst":
        print("已是跳过动画版 (%s)" % key)
        return 0
    out_path = args[1] if len(args) >= 2 else os.path.join(os.path.dirname(os.path.abspath(src_path)), v["out_name"])
    if os.path.abspath(out_path) == os.path.abspath(src_path):
        print("输出路径不能覆盖输入 ROM")
        return 2
    out = apply_patch(data, key)
    if os.path.exists(out_path) and not force:
        if md5(open(out_path, "rb").read()) == md5(out):
            print("输出已存在且一致:", out_path)
            return 0
        print("输出已存在，使用 --force 覆盖:", out_path)
        return 2
    open(out_path, "wb").write(out)
    print("识别: %s %s" % (key, v["version"]))
    print("输出 MD5:", md5(out))
    print("输出 CRC32: %08X" % (zlib.crc32(out) & 0xFFFFFFFF))
    print("已写入:", out_path)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
